-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODExd6bead0ed08f$doc_commission_for_the_investigation_of_abuse_of_author_ity_act_2048_2048_commission_for_the_investigation_of_abus$CODExd6bead0ed08f$,$CODExfa98b6f3ce68$Commission for the Investigation of Abuse of Author ity Act, 2048$CODExfa98b6f3ce68$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2048,1991,26,$CODEx845628b753fc$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "1\nCommission for the Investigation of Abuse of Author ity Act, 2048 \n(1991) \nDate of authentication and publication:  \n       4 Mangsir  2048 (  20 \nth \n nov, 1991)  \nAct Number 34 of the Year 2063", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Commission for the Investigation of Abuse of Authority (First Amendment) Act,2048 (1991)             – 2049/2/2/6", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Commission for the Investigation of Abuse of Authority (Second Amendment) Act, 2059 (2002 )       –2059/4/30/5", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "The Act Amending Some Nepal laws, 2063     –2063/6/28", "content": "Preamble: Whereas it is desirable to make provision relating to the functions, duties, \npowers and working procedures of the Commission for  the Investigation of Abuse of \nAuthority,  \n Now therefore \n, Parliament has enacted this Act in the 20 th  year of the reign of \nHis Majesty King, Birendra Bir Bikram Shah Dev.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 1", "title": "Chapter 1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title, Extent and Commencement  (1) This Act may be called the", "content": "Commission for the investigation of abuse of authority Act,2048 (1991), \n  (2) This Act shall be extend throughout Nepal, an d shall also be applicable  \nto all Nepali citizens, wherever they may have been residing outside Nepal. \n (3) It shall come into force immediately. \n(2) Definitions : In this Act, the subject or context otherwise req uires: - \n(a) \"Constitution\" means the Interim Constitution o f Nepal, 2063 ♣. \n(b) \"Commission\" means the Commission for the Inves tigation of Abuse of \nAuthority. \n(c) \"Commissioner\" includes the Chief Commissioner of the Commission, \n∇(d) \"Person holding a public post\" means any person  who is holding a post of \n                                                             \n♣ At present the prevails Interim Constitution of Nepal, 2063  \n 2\nresponsibility or is entitled to exercise any right  in pursuance of the \nConstitution, other prevailing laws or decisions or  orders of the concerned \nbody or authority and the term shall also mean an o fficial or employee \nholding any post in a public institution. \n∇(e) \"Public Institution\" means the following instit utions: \n(1)   A company, bank or committee fully or partly owned or controlled \nby Government of Nepal  or commissions, organizatio ns, authority, \ncorporations, academy, boards, centers, councils or  any other \norganized institution of such nature established by  His Majesty's \nGovernment, \n(2) Universities, campuses, schools, research cente rs and any other \nacademic or educational institutions run by Governm ent of Nepal or \nreceiving full or partial grants from Government of Nepal, \n(3) Local bodies constituted under the Local Self-G overnance \n Act,2055 (1999), \n(4) Institutions run with loans, grants or guarante e of the Government \n of Nepal. \n(5) Institutions with full or partial ownership or control of the \n institutions stated in Sub-Clauses (1), (2), (3) o r (4), \n(6) Any other institution designated as public inst itution by the \n Government of Nepal by publishing a notification i n  the Nepal \n Gazette. \n (f) \"Investigation Officer\" means a person designa ted under this Act for \nconducting inquiries and investigations on abuse of authority. \n(g) \"Improper Conduct\" means any act as mentioned i n Section 3, committed \n                                                                                                                                                                                                     \n∇ Amended  by the second Amendment. \n∇ Amended by the second Amendment. \n 3\nby a person holding a public post. \n∇ (h) \"Corruption\" means an offence punishable under  the prevailing laws \nrelating to the prevention of corruption. \n(i) \"Abuse of Authority\" means an improper act or c orruption  as mentioned in \nClauses (g) or (h), \n/crossoutline (j) \"Court\" means the court pursuant to Sub-sectio n (1) of Section 34 , \n/crossoutline (k)  \"Authority\" means the authority provided for in prevailing laws or \nagreements or any other written documents relating to terms and conditions \nof service of a person who is holding a public post , and the term shall also \napply to a person authorized to appoint, dismiss fr om service or supervise \nthe works of such persons. \n3 Improper conduct: Any of the following acts taken willfully or negligently by a \nperson holding a public post shall be regarded as an improper Conduct: \n(a) to refuse to do anything within the jurisdictio n to do anything beyond the \njurisdiction . \n(b) to comply with the mandatory procedures while t aking a decision or issuing \nan order. \n(c) to exercise powers vested in him/her for any ob jective or purpose in \ncontravention of the appropriate law, decision or order. \n(d) to exercise discretionary powers in a mala fide  or arbitrary manner. \n(e) to create unauthorized obstruction in the work of any other office, authority \nor employee, or compelled them to perform any unaut horized action by \nexerting pressure on such office, authority or employee. \n(f) to fail to do anything which one should have do ne, or send to another office \nor authority, evading responsibility, or \n(g) to fail to discharge any duty pertaining to the  post; which is required to \n                                                             \n∇ Amended by second Amendment. \n/crossoutline Inserted by Second Amendment. \n/crossoutline Inserted by Second Amendment. \n 4\ndischarge according to the nature of the post . \n/crossoutline (h)  to cause to work in one's own interest to a p erson subordinate or person \nunder the influence through undue pressure or lure .   \n/crossoutline (i) to abuse the immunity, facilities or privilege s acquired in the capacity of a \npost.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter III", "title": "Chapter III", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "8", "title": "∇Complaints with regard to improper conduc t: (1) In case anyone commits", "content": "improper conduct having an adverse effect on matter s of public interests or \nconcern, anyone may file a complaint with the Commi ssion and in case of matters \nother than this, a person who is adversely affected  by the improper conduct may \nlodge a complaint. \nProvided that, in case the person adversely affecte d by improper conduct has \nalready died or unable to file a complaint due to  physical or mental incapacity, a \ncomplaint may be filed by his/her  heir or guardian as well. \n(2) The commission may pursuant to this Act conduct  an inquiry or \ninvestigation and take necessary action with regard  to an improper conduct being \n                                                             \n∝ Repealed by the Second Amendment. \n∇ Amended by the second Amendment. \n 6\ncommitted adversary affecting the matters of public  interest or concern upon \nreceiving any  information from any other source ev en a complaint has not been \nfiled pursuant to Sub-Section (1),  \n (3) While filing a complaint pursuant Sub-Section (1) on matters having an \nadverse impact on public interest  or concern, the complaint may be filed any time \nand with regard to matters other than this, complaints  shall be filed within 35 \ndays after the complainant comes to know of it. \n (4)  While submitting a complaint, the complainant  shall submit evidence in \nsupport of the complaint which are in his/her posse ssion or which he/she can \nobtain. \n9. \nVerification of complaints : Except when ∇the person adversely affected by \nimproper actions personally  files a complaint with the Commission, in case the  \ncomplaint is forwarded to the Commission by post or  by any other means, the \nCommission shall summon  ∇such complainant  to appear before it within seven \ndays after receiving such complaint for its verification. \n Provided that, in case the contents of the complai nt are found baseless   or \nunclear or confusing, the Commission may decide not  to take any action in respect \nthereto. The Commission shall inform the ∇person adversely affected by improper  \nconduct of such decision as early as possible. \n10  Procuring the relevant files and documents of evide nce  :  In case the \ncontents of the complaints, and any evidence if any  submitted by the complainant \nin respect thereto, provide reasonable grounds to believe that any person holding, a \npublic post has committed any improper conduct as m entioned in the complaint, \nthe Commission may procure the relevant files or do cuments of evidence from the \n                                                             \n∇ Amended by the second Amendment. \n∇ Amended by the second Amendment. \n∇ Amended by the second Amendment. \n 7\nappropriate office office-holder, or person, and in  case if a person can provide \nimportant information in respect thereto, the Commi ssion may also inquire  such \nperson. \n∇11. Procedure for departmental action : (1) In case any person holding a public \npost is deemed to have committed an improper conduc t or there is reasonable \nground to believe so from an investigation undertak en by the Commission, the \nCommission shall send a notification to such person  by enclosing all the details \nobtained from the investigation into the complaint filed against him/her requiring \nhim/her to submit a clarification within a prescribed period. \n   (2) While sending a notification pursuant to Sub -Section (1), the \ncomplaint filed against the person holding a public  post, all the details acquired \nfrom the investigation, the ground on which the all egations against him/her are \nbased or what kind of departmental action or punish ment or action he/she should \nface in case he/she is convicted of the charge must  be clearly mentioned in the \nnotification. \n∇12. Written request for departmental action : (1) In case, any person holding a \npublic post does not submit a clarification within the time as prescribed in Sub-\nsection (1) Section 11, or in case, in the opinion of the Commission, the \nclarification so submitted is not deemed satisfactory, the Commission may write to \nthe appropriate authority  to caution or to take de partmental action against him/her \nupon stating the reasons and grounds based on the degree of offence. \n(2) In case, the request in writing has been receiv ed pursuant to  Sub-\nSection (1), the concerned authority shall propose an appropriate penalty and shall \ninform the Commission within three months of taking  departmental action as per \n                                                             \n∇ Amended by the second Amendment. \n∇ Amended by the second Amendment. \n 8\nthe prevailing laws. In case the action has been in itiated in response to a complaint \nfiled by somebody else, the complainant must also be informed of this. \n(3) In case the appropriate authority fails to take  departmental action within \nthe time prescribed in Sub-Section (2) except as ot herwise having a reasonable \nground, the Commission may take an action against t he authority considering it as \nan improper conduct under this Act. \n/crossoutline12a.  To write for other necessary action : In case any person holding a public   post \ncommits an improper conduct and causes harm or loss  to Government of Nepal  or \npublic institutions, the Commission shall write to the concerned body or authority \nto make up for the losses incurred or to take any o ther necessary action deemed \nappropriate by the Commission. \n/crossoutline12b.  To issue an order for rectifying bad results : The Commission may write to \nthe concerned authority or department in order to r ectify the bad results arising out \nof the improper conduct committed by a  person holding a public post. \n  Provided that, in case the decision taken by the person holding a public post \nmay be appealed under the prevailing laws, the Commission shall not write in such \na way that it would have an influence on  such a decision. \n/crossoutline12c.  To inform the Commission : Upon  receiving  a response pursuant to Section \n12a or 12b, the concerned authority or body shall t ake action within three months \nand  inform the commission accordingly.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter IV", "title": "Chapter IV", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "14", "title": "Preliminary Probe Regarding Corruption : (1) In case there exist reasonable", "content": "grounds to believe on the basis of any complaint or  report, or from information \nreceived by the Commission from any other source, t hat a person holding a public \npost has committed an offence involving corruption, the Commission may conduct \na preliminary probe thereof secretly, \n(2) While conducting a preliminary probe of the off ence of corruption \nunder Sub-section (1), the Commission may exercise the power, vested in it under \nthis Act in respect to inquiries and investigations.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Clarification to be sought from the concerned perso n in case", "content": "information seems to be correct : If, in the course of a preliminary probe into \nany offence involving corruption under Sub-section (1) of Section 14, the \ncomplaint, report or information received by the Co mmission seems to be correct, \nthe Commission may demand clarifications from the p erson who has committed \noffence, as well as from other person implicated th erein, mentioning brief \nparticulars of the charges. \n∇16.  Detention of the accused : (1) In case there is adequate ground to believe t hat \nany person against whom the Commission has initiate d actions on charges of \ncorruption may conceal or destroy any evidence, or hamper or obstruct, or \n                                                             \n∇ Amended by the second Amendment. \n 10 \nadversely affect the action being undertaken by the  Commission, the Commission \nmay keep him/her in detention by providing with him /her a detention order in \nhis/her name under the prevailing law. \n(2) In case, as regards to the person in detention, it is deemed necessary to \ncontinue investigation by keeping him/her in detent ion for a longer period, than \ntwenty four hours to complete the process, commissi on shall seek the permission \nby producing him/her before the court. While seekin g permission from the court, \nallegations against him/her, and reasons for contin uing probe by keeping him/her \nin detention and contents of his/her statement, if at all, shall be clearly mentioned. \n(3) The person produced before the court for the pu rpose of seeking \npermission to keep in detention under Sub-Section ( 2) may apply at the court \nrequesting for his/her physical check-up. \n(4) In case, permission is requested under Sub-Sect ion (2) to keep in \ndetention, the court, upon scrutinizing the relevan t documents, shall decide \nwhether the investigation is going satisfactorily o r not, and if it is deemed \nsatisfactory, it may grant permission to keep in de tention for a maximum period of \nsix months, not exceeding one month at a time. \n(5) While requesting for an extended period of time to keep the accused in \ndetention under Sub-Section (4), the person in dete ntion may file an application at \nthe concerned court by detailing all the grounds an d reasons proving that his/her \ndetention is not necessary, if he/she so desires. \n∇17. Ipso Facto suspension : In case, any person holding a public post being i s \ndetained by the commission under Section 16 or Sub- section (4) of Section 19, \nsuch person shall be deemed to have been ipso facto  suspended from his/her post \nfor a period of such detention, and in if, the case  has been filed against him/her in \n                                                             \n∇ Amended by the second Amendment. \n 11 \nthe Court under Section 18, he/she shall be deemed to have been so suspended \nuntil the case is disposed off. The person so suspe nded shall be deemed unfit for \nany post in the government offices or public instit ution or any other post which \nmay cause financial burden to the loan or grant rec eived by the Government of \nNepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Filing of cases : In case, there exist reasonable grounds to believ e, on the basis of", "content": "action initiated under this Act, and inquiries and investigations conducted in \nrespect thereto, regarding a charge of corruption a gainst any person holding a \npublic post, that he/she has committed such offence , the Commission may ∇order \nthe investigation officer or any office of the Gove rnment of Nepal to file a case  \npursuant to the prevailing law.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter V", "title": "Chapter V", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "19", "title": "Powers of the Commission Relating to inquiries and Investigations  :(1)", "content": "While conducting inquiries and investigations into abuse of authority under this \nAct, the Commission may exercise the following powers: \n(a) Issue orders to submit to the Commission, or pr esent to the \nCommission within a specific time limit, relevant f iles or documents \nof evidence, or other materials, in the possession of any office or \nindividual, or \n(b) Summon a person against whom charges of abuse o f authority have \nbeen made or any person who, in the opinion of the Commission, \npossesses knowledge of the relevant facts, inquire such persons, and \nrecord their statements and issue questionnaires (Band sawal)  in \ntheir name as requires. \n(c)  Issue an order to the police to arrest a perso n who does not appear \n                                                             \n∇ Amended by the second Amendment. \n 12 \nbefore the commission within the prescribed period even receiving \nthe notice so issued by the commission. \n(2)  Upon receiving clarification, or recording  st atements of the person \nagainst whom charges of abuse of authority have bee n made, commission may \nrelease him/her after making him/her sign a bond st ipulating that he/she will \nappear before the Commission as required, or keep him/her on date. \n(3)  In case there exists a reasonable ground to be lieve that the person \nagainst whom action has been initiated on charges o f corruption may conceal or \ndestroy evidence against him/her, or hamper or obst ruct inquiry and investigations \nif he/she is allowed to continue in his/her post, t he Commission may write to the \nGovernment of Nepal or concerned institution, as th e case may be to suspend \nhim/her from the post. \n(4)  In case there exist reasonable ground to belie ve that the person \nagainst whom action has been initiated on charges o f corruption may abscond and \ndisappear, or in case any property appears to have been damaged, the Commission \nmay demand security in cash or collateral from him/ her pursuant to the prevailing \nlaw and in case such security in cash or collateral  is not provided, keep him/her in \ndetention. \n(5)  In case the Commission has written to any offi ce or individual to \nsubmit any document or other material, or furnish information about any matter, or \nin case the Commission has summoned any person to appear before it:- \n(a) In case such office does furnish such document or material within a \nreasonable time limit accordingly or does not furni sh information \nrelating thereto, the Commission may direct the con cerned Minister \nor institution to initiate departmental action agai nst the chief office-\nholder of the concerned office. \n(b) In case such person does not furnish the docume nt or materials \nwithin a reasonable time limit accordingly, or does  not furnish \ninformation relating thereto, or in case such perso n does not appear \n 13 \nbefore the Commission, the Commission may fine him/ her with an \namount not exceeding one thousand Rupees . \n(6)  In case any office or individual does not comp ly with the orders of \nthe Commission even after the departmental action i s taken, or a fine imposed, \npursuant to Sub-section (5), the Commission may iss ue a warrant of arrest for \narresting and producing the chief office holder or person, and have such office or \nperson furnish such document or material, or provid e necessary information. In \ncase the office holder or person who is arrested in  this manner does not furnish \nsuch document or material, or does not provide info rmation relating thereto, the \nCommission may issue an order to keep him/her in de tention for a period not \nexceeding seven days. \n(7)  In case the Commission has directed that depar tmental action be \ntaken or decided to impose a fine under Sub-section  (5), and in case the chief \noffice-holder or the concerned person submits a pet ition mentioning reasonable \ngrounds why he/she has not been able to comply with  the order of the \nCommission, so that such action should not be initi ated or such fine should not be \nimposed, and in case the reasons appear to be satis factory, the commission may \ncancel the order relating to such directive or fine. \n(8)  The Commission, if think necessary, shall have  authority to search \nor cause to  search of any place or to seize any ob ject, document or file as so \nrequired or to copy the document or file pursuant to the prevailing law .  \n(9) Except in circumstances when the Commission has  no power under \nthis Act to initiate an action, no person holding a  public post shall be granted \nimmunity from disclosing any information on the bas is of confidentiality in the \ncourse of proceedings before the Commission. \n(10) Every agency or office holder conducting inves tigations into abuse \nof authority shall conduct proceedings in camera, i nstead of taking open action \nleading to publicity; unless there is Prima Facie evidence against whom charges \nof abuse of authority has been made. \n 14 \n(11) In case a complaint is filed against a person holding politically \nappointed post or a member of the parliament, regar ding abuse of authority, the \nCommission shall conduct secret inquiries into such  complaints. If, in the course \nof such inquiries, it is found that there is ground  to prove the matters mentioned in \nthe complaint, then, ∇an action shall be initiated  under this Act in respect to such \ncomplaint, and the Commission shall inform the Prim e Minister of detailed \ninquiries in the case of a person holding any polit ically appointed post and the \nSpeaker or the Chairperson of the appropriate House  in the case of a member of \nParliament. \n(12) In course of the investigations or inquiries c arried out under this Act, \nin case, the charges are not proved on the ground o f the collected evidence, the \nCommission may issue a terminate order with support ing reasons for the same. \n Provided that, this Section shall not be deemed to  have obstructed the \nproceedings if fresh evidence on are found regarding the complaint. \n/crossoutline(13) In case a complaint is terminated pursuant to  Sub-Section (12), the \nconcerned person holding a public post and the complainant shall be so informed. \n/crossoutline(14) Notwithstanding anything contained in this Act , in case improper \nconduct is found to have been committed in course o f the investigation into \ncorruption or in case corruption is found to have b een committed in course of \ninquiries into improper conduct, actions shall be taken accordingly. \n/crossoutline(15) If an accused helps to the process of investig ation and inquiry to be \nconducted pursuant to this Act, the Commission may produce him/her to the cause \nas a witness and may request for commutation in penalty, fully or partially. \n                                                             \n∇ Amended by the second Amendment. \n/crossoutline Inserted by Second Amendment. \n/crossoutline Inserted by Second Amendment. \n/crossoutline Inserted by Second Amendment. \n 15 \n   Provided that, in case the assistance fails to c orroborate through other \nproof or evidence or the statement given in the con cerned court is against the \nassistance rendered in the Commission, lawsuit may be filed against such person, \nnotwithstanding anything contained in this Act or any other prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Appointment of Investigation Officer : (1) The commission may appoint /crossoutlineor", "content": "designate any Commissioner or any employee of the Commission or any employee \nof Government of Nepal or any institution, as an  I nvestigation Officer, as so \nrequiring in order to conduct Preliminary inquiries  and investigations into \nimproper conduct or offense involving corruption under this Act.  \n  Provided that, while appointing /crossoutlineor designating the employee of the \ngovernment or any institution as an Investigation O fficer, the Commission shall \nconsult with Government of Nepal or the Chief of th e concerned institution as the \ncase may be. \n(2)  The Investigation Officer appointed /crossoutlineor designated by the \nCommission under Sub-section (1) may exercise the p owers vested in the \nCommission under this Act in respect to inquiry and investigation.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter VI", "title": "Chapter VI", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "22", "title": "Allotment of Functions By Chief Commissioner : In case other", "content": "Commissioners also have been appointed in addition to the Chief Commissioner in \nthe Commission, the Chief Commissioner shall have p ower to allot work and \nprescribe the functions of individual each Commissioner.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Secrecy of Information  : (1) Any notice or information obtained in the co urse", "content": "of inquiries and investigations into abuse of autho rity under this Act, and evidence \nreceived or collected by the Commission, shall not be disclosed to the public, or \nthe communication media. \n Provided that, this provision shall not prejudice the power of the \nCommission to conduct inquiries and investigations into abuse of authority, or \nsubmit report related thereto, or publish notices o r particulars necessary for \ninitiating action, \n(2) Notwithstanding anything contained in Sub-secti on (1), the \nCommission may conduct an open probe, inquiry and investigation into any matter \nconsidered by it to be of public importance. \n                                                             \n/crossoutline Inserted by Second Amendment. \n 17 \n/crossoutline23a.  To acquire statement or to freeze transaction:  (1) Notwithstanding anything \ncontained in the prevailing laws, in case, in course of the investigation into charges \nof corruption, any person is learnt, from any sourc e, to have been involved in \ntransactions or have operated an account in banks o r financial institutions within \nthe country or abroad, the Commission may order fre ezing of such transaction or \naccount. As ordered by the Commission, the concerne d bank or financial \ninstitution must freeze such transactions or account. \n      Provided that, as regards freezing of transac tions or bank accounts in foreign \ncountries, such transaction or bank account shall b e caused to be frozen through \ndiplomatic channels. \n (2) The Commission may impose a maximum fine of fi fty thousand Rupees \nto the Chief of the concerned bank or financial ins titution based in Nepal for its \nfailure to freeze transaction or account pursuant to Sub-Section (1). \n  (3) The Commission, if deemed necessary in course  of the investigation, \n may demand a property statement of a person holdin g a public post or may freeze \n such property. \n/crossoutline23b. Order to ban issuance of passport or to put it on h old:  Notwithstanding \nanything contained in the prevailing laws, the Comm ission may order the \nconcerned body not to issue a passport to any accused or to put it on hold in case it \nhas already been issued in view of the gravity of t he offence, the circumstances in \nwhich the offence was committed, situation and the degree of offence and the \npunishment to be  meted  if proved guilty. \n/crossoutline23c. Restriction to leave place:  In case an action has already been initiated under  this \nAct, the Commission may issue an order prohibiting him/her to leave any place or \n                                                             \n/crossoutline Inserted by Second Amendment. \n/crossoutline Inserted by Second Amendment. \n/crossoutline Inserted by Second Amendment. \n 18 \nto go to any places without the permission of the C ommission considering the \nseriousness of the offence, the circumstances in wh ich the offence was committed \nand the punishment to be meted out if proved guilty. \n∇24.  Punishment for obstruction : In case any person willfully obstructs any action  \nor process relating to inquiries and investigations  under this Act, the appropriate \nCourt may punish him/her with a fine of not more th an fives thousand Rupees  or \nwith imprisonment for a term not exceeding sixth mo nths, or with both, on the \nbasis of a report of the Commission. \n/crossoutline24a.  Provision with regard to service of notice  :  (1) Notwithstanding anything \ncontained in the prevailing laws, while issuing  a notice in the name of a foreign \nnational on charges under this Act, such notice sha ll be issued in the name of the \noffice or the representative in Nepal, if at all, a nd this shall be deemed to have \nbeen duly served. \n  (2) In case the office or representative pursuant  to Sub-Section (1) is not \nfound, notice shall be served to place of main tran sactions or to the permanent \naddress or to the address for correspondence of suc h person in which he/she is \ndoing transactions through telex, telefax or other means of telecommunication or \nthrough postal registry and the notice thus served shall be deemed to have been \nduly served. \n  (3) Notwithstanding anything contained in Sub-Sec tion (1) or (2), this \nSection shall not be deemed to become an obstructio n in serving notice in the \nname of any person residing in a foreign country as per a separate provision of any \ntreaty to which Government of Nepal or Nepal is a party. \n                                                             \n∇ Amended by the second Amendment. \n/crossoutline Inserted by Second Amendment. \n 19 \n/crossoutline24b. Publication of notification : While issuing a notification or serving a notice to a \nperson pursuant to this Act or any other prevailing  law, in case, a report has been \nreceived mentioning that the notification could not  be delivered or a notice could \nnot be served due to not finding. The address of su ch person or any other reason,  \nnotwithstanding anything in the prevailing  laws, t he commission shall publish a \npublic notice twice in the National level news pape r (In case of foreign in the \nEnglish language  daily newspaper) to appear before  within 30 days upon \nmentioning the briefs of the investigation by the c ommission or change sheet filed \nat the court  as the case may be, and such notifica tion or notice shall be deemed to \nhave been duly delivered or served notwithstanding anything in the other \nprevailing law .  \n/crossoutline24c. Punishment for making false complaints : In case any person without any \nreasonable ground lodges a false complaint against any public servant or a person \nholding public post or a person with a mala fide  intention of causing injury, the \nCommission may fine up to five thousand Rupees to such person if so proved.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "No Suit To be Entertained Against The Commission, C ommissioners Or", "content": "Employees of commission :No suit shall be instituted in any court in respec t to \nany action taken with bona fide  intention under this Act by the Commission or any \nCommissioner or employee of the Commission, or any employee or office deputed \nby the Commission, or to whom the Commission has delegated authority.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Cooperation may be obtained by the commission from other offices or", "content": "employees : (1) For the purpose of inquiries and investigation s into abuse of \nauthority,  the Commission may obtain the cooperati on of any Department or \noffice of the Government of Nepal, including the Po lice Headquarters, the \nNational Investigations Department and their subord inate office, or any institution, \nor the services of any  employee of such department, office or institution. \n                                                             \n/crossoutline Inserted by Second Amendment. \n/crossoutline Inserted by Second Amendment. \n 20 \n(2) In case the nature of the abuse of authority in to which the \nCommission is conducting inquiries and investigatio ns, makes it necessary to hold \nconsultations with any expert working in any depart ment, office, or institution, or \nto involve such expert in inquiries and investigati ons, the Commission may \nrequest the concerned department, office or institu tion to send him/her in \ndeputation for a specified period. \n(3) In case the Commission has sought the cooperati on of any \ndepartment, office or institution, or any employee working therein, pursuant to \nSub-section ( 1) or Sub-section (2), it shall be th e duty of such department, office \nor institution or employee to provide such cooperation to the Commission. \n27 ........ ∝ \n28  Commission May Offer Suggestions : (1) On the basis of facts which come \ninto its knowledge in the course of action taken by  it, the Commission may offer \nany of the following suggestions to the appropriate  office, office holder or \ninstitution: \n(a) In case the Commission feels that any law, deci sion, order or action \nis impractical, undesirable, or inconsistent, and s o must be amended, \nit may offer suggestions for amendment therein alon g with the \nreasons. \n(b) In case the Commission feels that Government of  Nepal or any \ninstitution, or any office or office holder of Gove rnment of Nepal or \nany institution, must remain vigilant on any issue,  or must take any \naction, it may offer suggestions about what type of  vigilance should \nbe adopted or action taken. \n(c) In case the Commission feels that any practice or procedure of \nGovernment of Nepal or any institution if defective , it may offer \n                                                             \n∝ Deleted by first Amendment. \n 21 \nsuggestions along with the reasons and bases to rec tify such defects \nand solve problems arising therefrom. \n(2)  Particulars of suggestions offered under Sub-s ection (1) shall be included in the \nannual report to be submitted by the Commission to the majesty under Clause (6) of Article 98 of \nthe Constitution. 1 \n∇29. Cases may be initiated against retired persons also : (1) nothing contained \nin this Act shall be deemed to have prevented the C ommission from instituting \ncases against any person in respect to corruption c ommitted by him during the \nperiod when he was holding a public post, even after he has retired from such post. \n  (2) Notwithstanding anything contained in this Ac t, in case any person \nholding a public post is found to have abused power s when he/she was holding the \npublic post and it was not possible to initiate act ion pursuant to this Act \nimmediately, nothing in this Act shall be deemed to  have prevented to take action \nagainst him/her even after retirement from the post for whatever reasons. \n/crossoutline29a. No obstruction in the proceeding and finalization o f the case : \nNotwithstanding anything contained in the prevailin g law, there shall be no \nconstraints in initiating proceedings or finalizing  the case even if the   accused or \ndefendant has died before or after filing of the case under this Act. \n/crossoutline29b.  Confiscation of property:  In case, any property earned by a person holding a  \npublic post or the property increased from it kept in his/her own name or in the \nname of any other person  is proved to have been ea rned through corruption under \nthis Act or other prevailing laws, such property shall be confiscated. \n  Provided that, in case the ownership of such prop erty has been transferred \nto any other person and while transferring the owne rship if the amount of such \n                                                             \n1\n This provision is not mentioned in the article of 119, 120 &121 of  Interim Constitution of Nepal, 2063  \n∇ Amended by the second Amendment. \n/crossoutline Inserted by Second Amendment. \n/crossoutline Inserted by Second Amendment. \n 22 \nproperty has been mentioned, such amount shall be c onsidered as a loan without \nany collateral (as good as kapali ) . \n/crossoutline29c.  To order freezing of the property of a foreigner : (1) In case any foreigner, \nsummoned as per the notice  issued by the Commissio n or pursuant to Section 24a \nwho fails to appear before the Commission within th e stipulated time, possesses \nany property or enjoys any right or has any concern  in the Nepal, the Commission \nmay put on hold such property or rights or concern or may issue an order requiring \nthe foreign national not to take such things outsid e the country and it shall be the \nduty of all to observe such order. \n  (2) The Commission may impose a fine of up to One  Hundred Thousand \nRupees to a person who fails to observe the order i ssued pursuant Sub-Section (1), \nand in case the non-observance of such order has ca used any harm, loss to the \nGovernment of Nepal or any public institution, such  harm or loss shall also be \nrecovered from him/her. \n∇30. Cases may also be initiated against other persons : (1) In case any person \nconsidered as public servant under the existing law  or any other person commits \ncorruption, the Commission may, under this Act or t he prevailing laws, initiate \ninvestigations and inquiries or may file case and may initiate other actions thereto. \n  (2) While undertaking investigations and inquirie s into cases of corruption \nunder this Act or under any other prevailing laws c ommitted by a person holding a \npublic post or by any other civil servant under the prevailing  law, the Commission \nmay initiate investigations and inquiries, may file  cases and take any other action \nagainst any person in case such person is found to have been involved in such \noffence. \n \n                                                             \n/crossoutline Inserted by Second Amendment. \n∇ Amended by the second Amendment. \n 23", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Action to be initiated by only one Agency on charge s corruption  : In case", "content": "action has been initiated against any person on cha rges of corruption in the same \ncase in the Commission as well as against other per son in other agencies in the \nsame case, the Commission may make arrangements to provide that such action \nmay be conducted through a single agency in respect to such charge. \n/crossoutline31a.  Provision relating to property details : (1) A person holding a public post \nfrom the date of holding of such post, and a person  who is in the public post from \nthe date of commencement of this Section shall subm it an updated statement of \ntheir property which is in their own or in their re latives name with source of it and \nproof there of within  sixty days and each year wit hin sixty days  of the expiry of \nevery fiscal year before the body or authority pres cribed by the Government of \nNepal by a notification in the Nepal Gazattee.    \n  (2) In case a person holding a public fails to su bmit a statement of \nhis/her property within the stipulated sixty days p ursuant to Sub-Section (1), the \nCommission shall impose a fine of five thousand Rup ees and ask to submit the \nstatement of the property within the next 30 days. If again the person holding the \npublic post does not submit the statement of proper ty within the extended \ntimeframe, the body or authority under Sub-Section (1) may initiate an \ninvestigation against him/her by assuming that the property in his/her own name or \nhis/her family member's name is illegal. \n  (3) The property statement so submitted under thi s Section shall be  kept \n confidential.  \n       Provided that, the statement may be given to  the concerned authority on \ndemand in course of initiating  investigation and inquiry under this Act. \n                                                             \n/crossoutline Inserted by Second Amendment. \n 24 \n/crossoutline31b. Auction of goods :(1) In case any goods or items seized in connectio n with \noffences punishable under this Act seem likely to d evelop rust if kept for long or \nsuffer breakage or cause losses or decay or depreci ate or have no owner or are not \nlikely to be maintained for lack of space, such ite ms or goods shall be auctioned \noff upon fulfilling procedures as mentioned in the prevailing law. \n  (2) The amount received from the auction shall be  credited in a deposit \nbank account. In case such items are declared to be  given to the concerned owner, \nonly the amount received from auction of such items shall be refunded.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Commission may regulate its Working Procedure : The Commission may", "content": "regulate its working procedure itself. \n/xrhombus33.  Annual Reports : The Commission shall submit to the President an a nnual \nreport on the works it has performed in accordance with this Constitution; and the \nPresident shall arrange to submit such report to th e Legislature-Parliament \nthrough the Prime Minister. \n∇34.  Adjudicating authority : (1) The power to hear a case filed under this Act  shall \nbe vested in the court as prescribed by the Government of Nepal upon publishing a \nnotification in the Nepal Gazette. \n  (2) The court prescribed pursuant to of Sub-Secti on (1), while initiating and \nfinalizing cases lodged under this Act, shall exerc ise the power and procedure as \nthe special court under the prevailing law. \n  (3) The verdict handed down by the court pursuant  to Sub-Section (1) \n shall be appealed at the Supreme Court. \n                                                             \n/crossoutline Inserted by Second Amendment. \n/xrhombus According to the Article 121 of Interim Constitution, 2063   \n∇ Amended by the second Amendment. \n 25 \n  (4) Government of Nepal shall be the plaintiff in  cases instituted under this \nAct on charges of corruption. \n∇35. To initiate cases : (1) In case any person holding a public post or a ny public \nservant under prevailing laws or other person is fo und to have committed an \noffence of corruption, the Commission, itself under  this Act or any other \nprevailing law, shall file a lawsuit, appeal or rev iew petition in its own name or \nthrough the authority designated by it.   \n  (2) The government attorney or an attorney appoin ted by the Commission \nin coordination with the Office of the Attorney Gen eral shall plead, advocate or \ndefend on cases filed pursuant to Sub-Section (1). \n/crossoutline35a.  Provision for reward:  The Commission may give a due reward to any person  \nwho helps the Commission in investigation, inquirie s or in collecting evidence  \nabout an offence, which is punishable under this Act. \n/crossoutline35b.  The Commission may carry out other functions : (1) The Commission may \nmaintain necessary coordination with the national o r international institutions \nestablished with the objective of controlling or pr eventing corruption or enhance \nrelation or mutual cooperation with such institutions. \n  (2) The Commission, if deemed necessary may carry  out research and \ndevelop processes to prevent corruption or improper  conduct through promotional \nactivities with a view to promoting information on such matters. \n/crossoutline35c.  Appea l: One may appeal, against the order handed down by the Commission for \nany fine or realizing any amount of money or other order, before the concerned \ncourt. \n                                                             \n∇ Amended by the second Amendment. \n/crossoutline Inserted by Second Amendment. \n/crossoutline Inserted by Second Amendment. \n/crossoutline Inserted by Second Amendment. \n 26 \n/crossoutline35d.  As per prevailing laws :  Matters contained in this Act shall be taken as per \n this  Act and in other matters action shall be tak en as per other prevailing laws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Provisions regarding complaints or actions transfer red from the", "content": "Commission for the Prevention of Abuse of Authority  : (1) Petitions and \ncomplaints transferred to the Commission under Clau se (5) of Article 130 of the \nConstitution shall be deemed to have been filed und er this Act and the \nCommission subject to the provisions of this act th ereto shall take action \naccordingly. \n(2)  If inquiries and investigations have been comp leted, but no suit yet have \nbeen filed, the Commission may treat the action as terminated under this \nAct, or send it to the concerned office for further  action, or issue an order \nunder Section 18 to file a suit in the  concerned Court. \n37. \nPower to frame Rules : The Commission may frame Rules in order to \nimplement this Act, Such Rules shall come into forc e after they are published in \nthe Nepal Gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Repeal  : The Commission for the Prevention of Abuse of Au thority Rule, 2034", "content": "(1977) has been repealed.  \nNote : (1) The  words changed by  The Act Amending Some Nepal laws, 2063  :- \n   \"Government of Nepal\" Instead of \"His majesty's Government\"  \n (2) The following words are changed by commission for the abuse of Authority (second \nAmendment)   Act, 2059 (2003)  \n  (a) \"Public Institution\" instead of \"Institution\"  \n  (b) \" Concerned Court\" instead of \"Appellate Cour t\" \n  \n                                                             \n/crossoutline Inserted by Second Amendment.", "children": []}]}]$CODEx845628b753fc$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
